html:
{%- set primary_dp = (doc.customer and frappe.get_all('DP Details', filters={'parent': doc.customer, 'is_primary': 1}, fields=['*'], limit=1)) or [] -%}
{%- if not primary_dp and doc.customer -%}
  {%- set primary_dp = frappe.get_all('DP Details', filters={'parent': doc.customer}, fields=['*'], limit=1) or [] -%}
{%- endif -%}
{%- set primary_dp = primary_dp[0] if primary_dp else None -%}
{%- set primary_bank = (doc.customer and frappe.get_all('Bank Details', filters={'parent': doc.customer, 'is_primary': 1}, fields=['*'], limit=1)) or [] -%}
{%- if not primary_bank and doc.customer -%}
  {%- set primary_bank = frappe.get_all('Bank Details', filters={'parent': doc.customer}, fields=['*'], limit=1) or [] -%}
{%- endif -%}
{%- set primary_bank = primary_bank[0] if primary_bank else None -%}
{%- set company = frappe.get_doc('Company', doc.company) -%}
{%- set customer = frappe.get_doc('Customer', doc.customer) if doc.customer else None -%}
{%- set _addr_link = frappe.db.get_value('Dynamic Link', {'link_doctype': 'Company', 'link_name': company.name, 'parenttype': 'Address'}, 'parent') -%}
{%- set company_address = frappe.get_doc('Address', _addr_link) if _addr_link else None -%}
{%- set company_bank_account = frappe.db.get_value('Bank Account', {'company': company.name, 'is_default': 1}, ['bank', 'bank_account_no', 'branch_code', 'iban'], as_dict=True) -%}
{%- set agent_name = (frappe.db.get_value('Sales Partner', doc.sales_partner, 'partner_name') if doc.sales_partner else (frappe.db.get_value('User', doc.owner, 'full_name') or doc.owner)) -%}

{# ── Payment derivation ─────────────────────────────────────── #}
{%- set grand_total = doc.grand_total or 0 -%}
{%- set outstanding = doc.outstanding_amount or 0 -%}
{%- set paid_amount = grand_total - outstanding if grand_total else 0 -%}
{%- set is_overdue = (doc.due_date and doc.due_date < frappe.utils.today() and outstanding > 0) -%}
{%- if doc.docstatus == 0 -%}
  {%- set status_label, status_class = 'Draft', 'pst-pill-draft' -%}
{%- elif doc.docstatus == 2 -%}
  {%- set status_label, status_class = 'Cancelled', 'pst-pill-cancel' -%}
{%- elif outstanding <= 0 -%}
  {%- set status_label, status_class = 'Paid', 'pst-pill-paid' -%}
{%- elif paid_amount > 0 -%}
  {%- set status_label, status_class = 'Partly Paid', 'pst-pill-partial' -%}
{%- elif is_overdue -%}
  {%- set status_label, status_class = 'Overdue', 'pst-pill-overdue' -%}
{%- else -%}
  {%- set status_label, status_class = 'Unpaid', 'pst-pill-unpaid' -%}
{%- endif -%}

{# ── Payment history (linked Payment Entries) ───────────────── #}
{%- set payment_refs = frappe.get_all('Payment Entry Reference', filters={'reference_doctype': 'Sales Invoice', 'reference_name': doc.name, 'docstatus': 1}, fields=['parent', 'allocated_amount']) or [] -%}
{%- set payments = [] -%}
{%- for ref in payment_refs -%}
  {%- set pe = frappe.db.get_value('Payment Entry', ref.parent, ['name', 'posting_date', 'mode_of_payment', 'reference_no'], as_dict=True) -%}
  {%- if pe -%}
    {%- set _ = payments.append({'name': pe.name, 'date': pe.posting_date, 'amount': ref.allocated_amount, 'mode': pe.mode_of_payment or '', 'ref_no': pe.reference_no or ''}) -%}
  {%- endif -%}
{%- endfor -%}

<div class="pst-wrap">

  <!-- ── Brand band ────────────────────────────────────── -->
  <div class="pst-brand">
    <div class="pst-brand-left">
      <div class="pst-co">{{ company.company_name }}</div>
      {%- if company_address %}
      <div class="pst-co-addr">
        {{ company_address.address_line1 or '' }}{% if company_address.address_line2 %}, {{ company_address.address_line2 }}{% endif %}, {{ company_address.city or '' }}{% if company_address.pincode %} {{ company_address.pincode }}{% endif %}{% if company_address.state %}, {{ company_address.state }}{% endif %}
      </div>
      {%- endif %}
      <div class="pst-co-meta">
        {%- if company.gstin %}GSTIN <strong>{{ company.gstin }}</strong>{% endif %}
        {%- if company.get('pan') %} &nbsp;·&nbsp; PAN <strong>{{ company.get('pan') }}</strong>{% endif %}
        {%- if company_address and company_address.gst_state_number %} &nbsp;·&nbsp; State Code <strong>{{ company_address.gst_state_number }}</strong>{% endif %}
      </div>
    </div>
    <div class="pst-brand-right">
      <div class="pst-doctitle">Share Transfer Order</div>
      <div class="pst-doc-no">{{ doc.name }}</div>
      <div class="pst-doc-date">{{ frappe.utils.formatdate(doc.posting_date, 'd MMM yyyy') }}</div>
      <div class="pst-pill {{ status_class }}">{{ status_label }}</div>
      <div class="pst-doc-meta">
        <div class="pst-row"><span class="pst-k">Ref</span><strong>{{ doc.po_no or doc.name }}</strong></div>
        <div class="pst-row"><span class="pst-k">Mode</span>{{ doc.payment_terms_template or 'Demat Transfer' }}</div>
        <div class="pst-row"><span class="pst-k">Agent</span>{{ agent_name or '—' }}</div>
      </div>
    </div>
  </div>

  <!-- ── Buyer card ──────────────────────────────────────── -->
  <div class="pst-buyer">
    <div class="pst-h">Buyer</div>
    <div class="pst-buyer-name">{{ (customer.customer_name if customer else doc.customer_name) }}</div>
    <div class="pst-kv">
      {%- if primary_dp %}
        <div class="pst-kv-row"><div class="pst-k">Demat</div><div class="pst-vv">{{ primary_dp.client_id or '' }} / {{ primary_dp.dp_id or '' }} &nbsp;·&nbsp; {{ primary_dp.dp_name or '' }}</div></div>
      {%- endif %}
      {%- if primary_bank %}
        <div class="pst-kv-row"><div class="pst-k">Bank</div><div class="pst-vv">{{ (primary_bank.bank_name or '') }} &nbsp;·&nbsp; A/C {{ primary_bank.ac_number or '' }} &nbsp;·&nbsp; IFSC {{ primary_bank.bank_code or '' }}</div></div>
      {%- endif %}
      <div class="pst-kv-row"><div class="pst-k">PAN</div><div class="pst-vv">{{ (customer.pan if customer else '') or (primary_dp.primary_bo_pan if primary_dp else '') or '—' }}</div></div>
      {%- if customer and (customer.email_id or customer.mobile_no) %}
        <div class="pst-kv-row"><div class="pst-k">Contact</div><div class="pst-vv">{{ customer.email_id or '' }}{% if customer.email_id and customer.mobile_no %} &nbsp;·&nbsp; {% endif %}{{ customer.mobile_no or '' }}</div></div>
      {%- endif %}
    </div>
  </div>

  <!-- ── Securities table ───────────────────────────────── -->
  <table class="pst-table">
    <thead>
      <tr>
        <th style="width:54%">Security</th>
        <th class="pst-num" style="width:14%">Quantity</th>
        <th class="pst-num" style="width:14%">Rate</th>
        <th class="pst-num" style="width:18%">Amount</th>
      </tr>
    </thead>
    <tbody>
      {% for row in doc.items %}
      <tr>
        <td>
          <div class="pst-item-name">{{ row.item_name }}{% set isin = frappe.db.get_value('Item', row.item_code, 'custom_isin') %}{% if isin %}<span class="pst-isin">{{ isin }}</span>{% endif %}</div>
          {%- if primary_dp %}<div class="pst-item-loc">Demat · {{ (primary_dp.dp_name or '')|upper }} · {{ primary_dp.client_id or '' }} / {{ primary_dp.dp_id or '' }}</div>{% endif %}
        </td>
        <td class="pst-num">{{ '{:,.0f}'.format(row.qty) }} <span style="color:#8a948f;font-size:7.5pt;font-family:'Space Grotesk',sans-serif">{{ row.uom or 'Nos' }}</span></td>
        <td class="pst-num">₹{{ '{:,.2f}'.format(row.rate) }}</td>
        <td class="pst-num">₹{{ '{:,.2f}'.format(row.amount) }}</td>
      </tr>
      {% endfor %}
    </tbody>
  </table>

  <!-- ── Total bar (with words inline) ──────────────────── -->
  <div class="pst-totals">
    <div class="pst-tot-row">
      <div class="pst-tot-l">
        Total Consideration<span class="pst-qty">{{ '{:,.0f}'.format(doc.total_qty or 0) }} {% if doc.items %}{{ doc.items[0].uom or 'Nos' }}{% endif %}</span>
        <span class="pst-words">{{ frappe.utils.money_in_words(doc.grand_total, doc.currency) }}</span>
      </div>
      <div class="pst-tot-r">{{ doc.get_formatted('grand_total') }}</div>
    </div>
  </div>

  <!-- ── Payment summary strip — 4 columns: total / paid / outstanding / due ── -->
  <div class="pst-paystrip">
    <div class="pst-ps-cell">
      <div class="pst-ps-h">Grand Total</div>
      <div class="pst-ps-v">{{ doc.get_formatted('grand_total') }}</div>
    </div>
    <div class="pst-ps-cell">
      <div class="pst-ps-h">Paid</div>
      <div class="pst-ps-v {% if paid_amount > 0 %}pst-ps-paid{% else %}pst-ps-zero{% endif %}">{{ frappe.utils.fmt_money(paid_amount, currency=doc.currency) }}</div>
    </div>
    <div class="pst-ps-cell">
      <div class="pst-ps-h">Outstanding</div>
      <div class="pst-ps-v {% if outstanding > 0 %}pst-ps-out{% else %}pst-ps-zero{% endif %}">{{ frappe.utils.fmt_money(outstanding, currency=doc.currency) }}</div>
    </div>
    <div class="pst-ps-cell">
      <div class="pst-ps-h">Due Date</div>
      <div class="pst-ps-v">{{ frappe.utils.formatdate(doc.due_date, 'd MMM yyyy') if doc.due_date else '—' }}</div>
    </div>
  </div>

  <!-- ── Declaration + remit + payment history + signature ────────────── -->
  <div class="pst-twocol">
    <div class="pst-twocol-c">
      <div class="pst-decl">
        <div class="pst-h">Declaration</div>
        <ol>
          <li>Buyer to confirm the above transaction by counter-signing this copy.</li>
          <li>All benefits attached to the security up to the date of transfer shall be retained by {{ company.company_name }}.</li>
          <li>The Seller reserves the right to terminate before completion. On termination by the Seller, the Buyer is entitled to a penalty of 0.10% of the consideration amount.</li>
          <li>Outstanding amount (if any) is payable to the bank account listed under Remit To by the due date shown above.</li>
        </ol>
      </div>
    </div>
    <div class="pst-twocol-r">
      <div class="pst-bank">
        <div class="pst-h">Remit To</div>
        {%- if company_bank_account %}
          <div class="pst-bank-name">{{ company_bank_account.bank }}</div>
          <div class="pst-bank-row"><div class="pst-bk-k">A/C No</div><div class="pst-bk-v">{{ company_bank_account.bank_account_no or '—' }}</div></div>
          <div class="pst-bank-row"><div class="pst-bk-k">IFSC</div><div class="pst-bk-v">{{ company_bank_account.branch_code or '—' }}</div></div>
          {%- if company_bank_account.iban %}<div class="pst-bank-row"><div class="pst-bk-k">UPI</div><div class="pst-bk-v">{{ company_bank_account.iban }}</div></div>{% endif %}
          <div class="pst-bank-row"><div class="pst-bk-k">Name</div><div class="pst-bk-v">{{ company.company_name }}</div></div>
        {%- else %}
          <div class="pst-bank-name">Bank details to be shared separately</div>
          <div class="pst-bank-row"><div class="pst-bk-k">Contact</div><div class="pst-bk-v">+91 82775 40332 · accounts@mith.tech</div></div>
          <div class="pst-bank-row"><div class="pst-bk-k">Reference</div><div class="pst-bk-v">Quote {{ doc.name }} on the transfer narration</div></div>
        {%- endif %}
      </div>
      {%- if payments %}
      <div class="pst-paylog">
        <div class="pst-h">Payment History</div>
        <table>
          {%- for p in payments %}
          <tr>
            <td style="width:38%">{{ frappe.utils.formatdate(p.date, 'd MMM yy') }}</td>
            <td style="width:32%">{{ p.mode or p.name }}</td>
            <td>{{ frappe.utils.fmt_money(p.amount, currency=doc.currency) }}</td>
          </tr>
          {%- endfor %}
        </table>
      </div>
      {%- endif %}
      <div class="pst-sig">
        <div class="pst-sig-co">For {{ company.company_name }}</div>
        <div class="pst-sig-line">Authorised Signatory</div>
      </div>
    </div>
  </div>

  <div class="pst-foot">
    <span>Computer-generated · No physical signature required for system records</span>
    <span class="pst-foot-r">{{ doc.name }}</span>
  </div>

</div>
